import {WebGLPage, WebGLBrandedDivider} from '@github-ui/brand-webgl'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'

import {ContentfulSubnav} from '@github-ui/swp-core/components/contentful/ContentfulSubnav'
import {useContentfulData} from '@github-ui/swp-core/lib/hooks/use-contentful-data'
import {documentToPlainTextString} from '@github-ui/swp-core/lib/utils/analytics'
import {getLinkHref} from '@github-ui/swp-core/lib/utils/links'

import type {PrimerComponentHero} from '@github-ui/swp-core/schemas/contentful/contentTypes/primerComponentHero'
import type {PrimerComponentCtaBanner} from '@github-ui/swp-core/schemas/contentful/contentTypes/primerComponentCtaBanner'

import {FAQ, Hero, ThemeProvider} from '@primer/react-brand'

import {toPublicMonitoringPage} from '../lib/types/contentful'
import type {GenericSection} from '../lib/types/contentful'

import {publicMonitoringRoute} from './public-monitoring-route'
import styles from './PublicMonitoring.module.css'

const getHeroLabelText = (label: PrimerComponentHero['fields']['label']) =>
  typeof label === 'string' ? label : label?.fields.text

const getSection = <T extends PrimerComponentHero | PrimerComponentCtaBanner>(content: GenericSection[], id: string) =>
  content.find(({fields}) => fields.id === id)?.fields.content.at(0) as T | undefined

export function PublicMonitoring() {
  const {
    data: {contentfulRawJsonResponse},
  } = useRouteQuery(publicMonitoringRoute, 'mainQuery')

  const page = toPublicMonitoringPage(useContentfulData(contentfulRawJsonResponse))
  const {content = [], subnav} = page?.fields.template.fields ?? {}

  const heroSection = getSection<PrimerComponentHero>(content, 'securityPublicMonitoringSecurityHeroSection')
  const heroLabel = getHeroLabelText(heroSection?.fields.label)

  return (
    <ThemeProvider colorMode="light">
      <WebGLPage>
        <div className={styles.HeroContainer}>
          {subnav ? <ContentfulSubnav component={subnav} /> : null}

          {heroSection && (
            <div className="tmp-py-8">
              <Hero enableAnimation data-hpc align="center">
                {heroLabel && <Hero.Label>{heroLabel}</Hero.Label>}
                <Hero.Heading>{heroSection.fields.heading}</Hero.Heading>
                {heroSection.fields.descriptionRich && (
                  <Hero.Description className="text-wrap-balance">
                    {documentToPlainTextString(heroSection.fields.descriptionRich)}
                  </Hero.Description>
                )}
                {heroSection.fields.callToActionPrimary && (
                  <Hero.PrimaryAction href={getLinkHref(heroSection.fields.callToActionPrimary)}>
                    {heroSection.fields.callToActionPrimary.fields.text}
                  </Hero.PrimaryAction>
                )}
                {heroSection.fields.callToActionSecondary && (
                  <Hero.SecondaryAction href={getLinkHref(heroSection.fields.callToActionSecondary)}>
                    {heroSection.fields.callToActionSecondary.fields.text}
                  </Hero.SecondaryAction>
                )}
              </Hero>
            </div>
          )}
        </div>

        <div className="tmp-py-8">
          <FAQ variant="gridline">
            <FAQ.Heading>Frequently asked questions</FAQ.Heading>
            <FAQ.Item name="FAQ" open>
              <FAQ.Question>What happens once I turn public monitoring on?</FAQ.Question>
              <FAQ.Answer>
                GitHub will begin scanning for public contributions which can be associated back to your enterprise. If
                a match is found, the alert will be surfaced in your public monitoring list view. Anyone with the
                Enterprise Security Manager role will receive an email notification when new findings are discovered in
                real time.
              </FAQ.Answer>
            </FAQ.Item>
            <FAQ.Item name="FAQ">
              <FAQ.Question>How are secrets attributed back to my enterprise?</FAQ.Question>
              <FAQ.Answer>
                GitHub will attribute exposed secrets back to your enterprise based on enterprise membership. In the
                future, public monitoring will support additional heuristics like email matching for user and committer
                emails based on verified enterprise domains.
              </FAQ.Answer>
            </FAQ.Item>
            <FAQ.Item name="FAQ">
              <FAQ.Question>Who can use public monitoring?</FAQ.Question>
              <FAQ.Answer>
                Public monitoring is available to all customers with an existing GitHub Secret Protection or GitHub
                Advanced Security plan at no additional cost.
              </FAQ.Answer>
            </FAQ.Item>
          </FAQ>
        </div>

        <WebGLBrandedDivider params={{character: 'security', layout: 3}} className="mx-auto" />
      </WebGLPage>
    </ThemeProvider>
  )
}
